     1|#!/usr/bin/env node
     2|/**
     3| * IVX Independence Audit (BLOCK 47 phase 9).
     4| *
     5| * Verifies the IVX production codebase has zero Rork runtime dependency.
     6| * Checks:
     7| *   - no @rork-ai/* in expo/package.json dependencies/devDependencies
     8| *   - no withRorkMetro / @rork-ai/toolkit-sdk in expo/metro.config.js
     9| *   - no rork.json project config
    10| *   - no EXPO_PUBLIC_RORK_* / RORK_* / EXPO_PUBLIC_TOOLKIT_URL env keys in expo/.env
    11| *   - no Rork API URLs (rork.com / rork.app / rorktest.dev) in expo app code (.ts/.tsx)
    12| *   - no @rork-ai imports in expo app code
    13| *   - production build (tsc --noEmit) passes
    14| *   - health endpoint returns the deployed commit
    15| *
    16| * Exit code 0 = PASS, 1 = FAIL (prints exact file + line for each failure).
    17| *
    18| * Usage:
    19| *   node expo/scripts/ivx-independence-audit.mjs
    20| *   node expo/scripts/ivx-independence-audit.mjs --no-build   (skip tsc)
    21| */
    22|import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
    23|import path from 'node:path';
    24|import { fileURLToPath } from 'node:url';
    25|import { execSync } from 'node:child_process';
    26|
    27|const __filename = fileURLToPath(import.meta.url);
    28|const __dirname = path.dirname(__filename);
    29|const expoRoot = path.resolve(__dirname, '..');
    30|const repoRoot = path.resolve(expoRoot, '..');
    31|
    32|const SKIP_BUILD = process.argv.includes('--no-build');
    33|const failures = [];
    34|const passes = [];
    35|
    36|function fail(file, line, reason) {
    37|  failures.push({ file, line, reason });
    38|  console.log(`  ✗ FAIL  ${file}:${line} — ${reason}`);
    39|}
    40|function pass(label, detail) {
    41|  passes.push({ label, detail });
    42|  console.log(`  ✓ PASS  ${label} — ${detail}`);
    43|}
    44|
    45|function readText(p) {
    46|  try { return readFileSync(p, 'utf8'); } catch { return null; }
    47|}
    48|
    49|function lineOf(source, needle) {
    50|  const idx = source.indexOf(needle);
    51|  if (idx < 0) return null;
    52|  return source.slice(0, idx).split('\n').length;
    53|}
    54|
    55|console.log('\n[ivx-independence-audit] IVX Rork-free production audit');
    56|console.log(`[ivx-independence-audit] repo: ${repoRoot}`);
    57|console.log(`[ivx-independence-audit] mode: ${SKIP_BUILD ? 'skip-build' : 'full'}\n`);
    58|
    59|// 1. package.json — no @rork-ai/*
    60|const pkgPath = path.join(expoRoot, 'package.json');
    61|const pkg = JSON.parse(readText(pkgPath) || '{}');
    62|const allDeps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) };
    63|const rorkPkgs = Object.keys(allDeps).filter((k) => /@rork-ai\//.test(k));
    64|if (rorkPkgs.length === 0) pass('package.json', 'no @rork-ai/* in dependencies or devDependencies');
    65|else for (const k of rorkPkgs) fail('expo/package.json', '?', `${k} still declared (${allDeps[k]})`);
    66|
    67|// 2. metro.config.js — no withRorkMetro / @rork-ai/toolkit-sdk
    68|const metro = readText(path.join(expoRoot, 'metro.config.js')) || '';
    69|if (/withRorkMetro|@rork-ai\/toolkit-sdk/.test(metro)) {
    70|  const ln = lineOf(metro, 'withRorkMetro') || lineOf(metro, '@rork-ai/toolkit-sdk');
    71|  fail('expo/metro.config.js', ln ?? '?', 'still wraps with withRorkMetro / imports @rork-ai/toolkit-sdk');
    72|} else pass('expo/metro.config.js', 'plain Expo Metro config (no withRorkMetro)');
    73|
    74|// 3. rork.json absent
    75|if (existsSync(path.join(repoRoot, 'rork.json'))) {
    76|  fail('rork.json', '?', 'rork.json project config still present — delete on independent checkout');
    77|} else pass('rork.json', 'absent');
    78|
    79|// 4. .env — no EXPO_PUBLIC_RORK_* / RORK_* / EXPO_PUBLIC_TOOLKIT_URL
    80|const env = readText(path.join(expoRoot, '.env')) || '';
    81|const rorkEnvKeys = env.split('\n').filter((l) => /^(EXPO_PUBLIC_RORK_|RORK_|EXPO_PUBLIC_TOOLKIT_URL)/.test(l.trim()));
    82|if (rorkEnvKeys.length === 0) pass('expo/.env', 'no Rork-prefixed env keys');
    83|else for (const l of rorkEnvKeys) fail('expo/.env', l, 'Rork env key present: ' + l.split('=')[0]);
